var shouldDeferPlannedSourceContainer = function(room, plannedEntry, structureCounts, siteCounts) {
    if(!room || !plannedEntry || plannedEntry.structureType != STRUCTURE_CONTAINER) return false;

    let entry = plannedEntry.entry;
    if(!entry || entry.tag != 'source') return false;

    let requiredExtensions = CONTROLLER_STRUCTURES[STRUCTURE_EXTENSION][3] || 10;
    let currentExtensions = (structureCounts[STRUCTURE_EXTENSION] || 0) + (siteCounts[STRUCTURE_EXTENSION] || 0);
    return currentExtensions < requiredExtensions;
};

