var __isEqualTo = RoomPosition.prototype.isEqualTo;
RoomPosition.prototype.isEqualTo = function(x, y) {

    if(x && x.constructor == RoomPosition) {
        var roomName = x.roomName;
        y = x.y;
        x = x.x;
        var xEqual = false;
        if (this.x == 0 || this.x == 49) {
            xEqual = x == 0 || x == 49;
        } else {
            xEqual = this.x == x;
        }

        var yEqual = false;
        if (this.y == 0 || this.y == 49) {
            yEqual = y == 0 || y == 49;
        } else {
            yEqual = this.y == y;
        }

        return xEqual && yEqual;
    } else {
        return __isEqualTo(x, y);
    }
};
